// FILE: frontend/src/components/charts/TripChart.js
//
// --- VERSION 0.3.0-ALPHA ---
// - Adaptive sampling: max 200 points per PID.
// - SamplingIndicator shows when active.
// - Click-to-pan left/right halves of chart by half window size.
//

import React, { useMemo, useRef, useState } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
} from 'chart.js';
import zoomPlugin from 'chartjs-plugin-zoom';
import PIDSelector from '../shared/PIDSelector';
import SamplingIndicator from '../shared/SamplingIndicator';
import { sampleData } from '../../utils/samplingUtils';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, zoomPlugin);

export default function TripChart({
  log,
  selectedPIDs,
  onPIDChange,
  chartColors,
  visibleRange,
  setVisibleRange
}) {
  const chartRef = useRef(null);
  const [animating, setAnimating] = useState(false);

  const windowSize = visibleRange.max - visibleRange.min;

  // Slice current visible range
  const windowData = useMemo(() => {
    if (!log?.data) return [];
    return log.data.slice(visibleRange.min, visibleRange.max + 1);
  }, [log, visibleRange]);

  // Build datasets with adaptive sampling
  const { chartData, samplingActive } = useMemo(() => {
    if (!log?.data) return { chartData: { datasets: [] }, samplingActive: false };

    let samplingFlag = false;
    const datasets = [];

    selectedPIDs.forEach((pid, idx) => {
      if (pid === 'none') return;

      let points = windowData.map(row => row[pid]);
      if (points.length > 200) {
        points = sampleData(points, 200);
        samplingFlag = true;
      }

      datasets.push({
        label: pid,
        data: points,
        borderColor: chartColors[idx],
        pointRadius: 0,
        borderWidth: 2,
        tension: 0.4
      });
    });

    return {
      chartData: {
        labels: windowData.map((_, i) => i),
        datasets
      },
      samplingActive: samplingFlag
    };
  }, [windowData, selectedPIDs, chartColors]);

  const chartOptions = useMemo(() => ({
    responsive: true,
    maintainAspectRatio: false,
    animation: { duration: animating ? 500 : 0 },
    plugins: {
      legend: { display: true, labels: { color: '#FFFFFF' } },
      zoom: {
        pan: { enabled: true, mode: 'x' },
        zoom: { wheel: { enabled: true }, pinch: { enabled: true }, mode: 'x' }
      }
    },
    scales: {
      x: { ticks: { color: '#9CA3AF' } },
      y: { ticks: { color: '#9CA3AF' } }
    }
  }), [animating]);

  // Click-to-pan handlers
  const handlePanLeft = () => {
    if (!log?.data) return;
    setAnimating(true);
    const shift = Math.floor(windowSize / 2);
    setVisibleRange({
      min: Math.max(0, visibleRange.min - shift),
      max: Math.max(windowSize, visibleRange.max - shift)
    });
    setTimeout(() => setAnimating(false), 500);
  };

  const handlePanRight = () => {
    if (!log?.data) return;
    setAnimating(true);
    const shift = Math.floor(windowSize / 2);
    const maxIndex = log.data.length - 1;
    setVisibleRange({
      min: Math.min(maxIndex - windowSize, visibleRange.min + shift),
      max: Math.min(maxIndex, visibleRange.max + shift)
    });
    setTimeout(() => setAnimating(false), 500);
  };

  return (
    <div className="bg-gray-800 rounded-lg shadow-xl p-4 relative">
      {/* PID selectors */}
      <div className="flex items-center space-x-4 mb-2">
        {selectedPIDs.map((pid, index) => (
          <PIDSelector
            key={index}
            color={chartColors[index]}
            options={log?.columns || []}
            selectedValue={pid}
            onChange={(value) => onPIDChange(index, value)}
          />
        ))}
      </div>

      {/* Sampling indicator */}
      <SamplingIndicator active={samplingActive} />

      {/* Chart */}
      <div className="h-[56vh] relative">
        <Line ref={chartRef} options={chartOptions} data={chartData} />
        {/* Click zones */}
        <div
          className="absolute top-0 left-0 h-full w-1/2 cursor-pointer"
          onClick={handlePanLeft}
        />
        <div
          className="absolute top-0 right-0 h-full w-1/2 cursor-pointer"
          onClick={handlePanRight}
        />
      </div>
    </div>
  );
}
